     7 | pub fn decode(bytes: &str) -> Result<Msg, String> {
     8 |     if bytes.contains("ping") {
     9 |         return Ok(Msg::Ping);
    10 |     }
    11 |     if let Some(name) = bytes.strip_prefix("v:2|hello|") {
    12 |         return Ok(Msg::Hello(name.into()));
    13 |     }
    14 |     if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat|") {
    15 |         return sequence
    16 |             .parse::<u32>()
    17 |             .map(Msg::Heartbeat)
    18 |             .map_err(|_| "invalid heartbeat sequence".into());
    19 |     }
    20 |     Err("unknown".into())
    21 | }
    22 | 
    23 | pub fn encode(msg: &Msg) -> String {
    24 |     match msg {
    25 |         Msg::Ping => "ping".into(),
    26 |         Msg::Hello(name) => format!("v:2|hello|{}", name),
    27 |         Msg::Heartbeat(sequence) => format!("v:2|heartbeat|{}", sequence),
    28 |     }
    29 | }
    30 | 
    31 | pub fn ping_roundtrip() -> Result<Msg, String> {
    32 |     decode(&encode(&Msg::Ping))
    33 | }
